  "inlineSchema": "// ============================================================================\n// SCHEMA DO BANCO DE DADOS - AGROSMART\n// ============================================================================\n// Este arquivo define todos os modelos (tabelas) do banco PostgreSQL.\n// Após editar, rode: npx prisma migrate dev --name <nome_da_migration>\n// ============================================================================\n\ngenerator client {\n  provider      = \"prisma-client-js\"\n  // binaryTargets garante que o Prisma Client funcione tanto localmente\n  // (Windows/Mac) quanto no ambiente Linux do Render (produção)\n  binaryTargets = [\"native\", \"linux-musl-openssl-3.0.x\", \"debian-openssl-3.0.x\"]\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// ----------------------------------------------------------------------------\n// USUÁRIO - Conta do produtor rural\n// ----------------------------------------------------------------------------\nmodel User {\n  id       Int     @id @default(autoincrement())\n  name     String\n  email    String  @unique\n  password String // senha já em hash (bcrypt)\n  role     String  @default(\"user\")\n  avatar   String? // URL da foto de perfil (Cloudinary)\n  phone    String?\n  timezone String? @default(\"America/Sao_Paulo\")\n  language String? @default(\"pt-BR\") // pt-BR | en-US | es-ES\n\n  // Controle de plano/assinatura (Mercado Pago)\n  plan             String    @default(\"free\") // free | pro | enterprise\n  planExpiresAt    DateTime?\n  mpSubscriptionId String?\n\n  // Recuperação de senha\n  resetToken        String?\n  resetTokenExpires DateTime?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  fazendas          Fazenda[]\n  pushSubscriptions PushSubscription[]\n}\n\n// ----------------------------------------------------------------------------\n// FAZENDA - Propriedade rural cadastrada pelo usuário\n// ----------------------------------------------------------------------------\nmodel Fazenda {\n  id          Int    @id @default(autoincrement())\n  nome        String\n  localizacao String // \"Cidade, UF\" - usado para buscar previsão do tempo\n  area        Float // área em hectares\n  cultura     String // cultura principal (ex: Soja, Milho, Gado)\n  status      String @default(\"ativa\")\n\n  userId Int\n  user   User @relation(fields: [userId], references: [id])\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  sensores   Sensor[]\n  alertas    Alerta[]\n  irrigacoes Irrigacao[]\n  documentos Documento[] // NOVO: documentos da propriedade (INCRA, ITR, GTA, etc.)\n}\n\n// ----------------------------------------------------------------------------\n// SENSOR - Dispositivo de monitoramento (Arduino/ESP32) instalado na fazenda\n// ----------------------------------------------------------------------------\nmodel Sensor {\n  id            Int       @id @default(autoincrement())\n  codigo        String    @unique // identificador legível (ex: TEMP-01)\n  tipo          String // Temperatura, Umidade, Solo, pH, etc.\n  status        String    @default(\"online\") // online | offline | unstable\n  bateria       Int       @default(100)\n  token         String?   @unique // token usado pelo hardware para autenticar\n  ultimaLeitura DateTime?\n\n  fazendaId Int\n  fazenda   Fazenda @relation(fields: [fazendaId], references: [id])\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  leituras Leitura[]\n}\n\n// ----------------------------------------------------------------------------\n// LEITURA - Histórico de valores enviados por um sensor\n// ----------------------------------------------------------------------------\nmodel Leitura {\n  id        Int      @id @default(autoincrement())\n  sensorId  Int\n  sensor    Sensor   @relation(fields: [sensorId], references: [id])\n  valor     Float\n  unidade   String // °C, %, ppm, etc.\n  createdAt DateTime @default(now())\n}\n\n// ----------------------------------------------------------------------------\n// ALERTA - Notificação gerada automaticamente (clima, sensor, documentos, etc.)\n// ----------------------------------------------------------------------------\nmodel Alerta {\n  id        Int     @id @default(autoincrement())\n  tipo      String // info | success | warning | danger\n  titulo    String\n  descricao String\n  lido      Boolean @default(false)\n\n  fazendaId Int\n  fazenda   Fazenda @relation(fields: [fazendaId], references: [id])\n\n  createdAt DateTime @default(now())\n}\n\n// ----------------------------------------------------------------------------\n// IRRIGACAO - Zona de irrigação controlável\n// ----------------------------------------------------------------------------\nmodel Irrigacao {\n  id      Int       @id @default(autoincrement())\n  zona    String // nome da zona (ex: \"Setor A - Soja Norte\")\n  ativa   Boolean   @default(false)\n  fluxo   Float     @default(0) // L/min quando ativa\n  duracao Int       @default(30) // duração padrão em minutos\n  proxima DateTime? // próxima execução agendada\n\n  fazendaId Int\n  fazenda   Fazenda @relation(fields: [fazendaId], references: [id])\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\n// ----------------------------------------------------------------------------\n// PUSH SUBSCRIPTION - Inscrição de notificações push do navegador\n// ----------------------------------------------------------------------------\nmodel PushSubscription {\n  id        Int      @id @default(autoincrement())\n  userId    Int\n  user      User     @relation(fields: [userId], references: [id])\n  endpoint  String   @unique\n  keys      String // JSON serializado com { p256dh, auth }\n  createdAt DateTime @default(now())\n}\n\n// ----------------------------------------------------------------------------\n// DOCUMENTO - NOVO: Documentos da propriedade rural\n// ----------------------------------------------------------------------------\n// Armazena documentos como INCRA, ITR, CCIR, Matrícula, GTA (gado), etc.\n// O arquivo em si é hospedado no Cloudinary; aqui guardamos apenas a\n// referência (URL) e os metadados para controle de vencimento.\n// ----------------------------------------------------------------------------\nmodel Documento {\n  id             Int       @id @default(autoincrement())\n  nome           String // nome dado pelo usuário (ex: \"ITR 2025\")\n  tipo           String // INCRA | ITR | CCIR | MATRICULA | GTA | OUTRO\n  arquivoUrl     String // URL do arquivo no Cloudinary\n  arquivoTipo    String // mime type (application/pdf, image/jpeg, etc.)\n  numero         String? // número do documento/registro (opcional)\n  dataEmissao    DateTime? // data de emissão (opcional)\n  dataVencimento DateTime? // data de vencimento - usada para gerar alertas\n\n  fazendaId Int\n  fazenda   Fazenda @relation(fields: [fazendaId], references: [id])\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n",
